window.MG_LAZY_DATA["data/lazy/resources/security-v26-054-c1c385f6a3a816fe.json"]={sha256:"c1c385f6a3a816fecaaf67897f9c4d726c7944d7550fda1fd6a55ab97761e474",value:{"sources":[{"id":"v26-case-55edad2747a7de1c","url":"https://semgrep.dev/docs/writing-rules/rule-syntax","title":"Semgrep rule syntax","titleEn":"Semgrep rule syntax","publisher":"Semgrep","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-054","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-054","related":[{"id":"security-v26-055","referenceUrls":["https://codeql.github.com/docs/writing-codeql-queries/"],"title":"CodeQL：資料流路徑與人工分流","titleEn":"CodeQL: data-flow paths and evidence triage","why":"用兩課的可觀察驗收條件比較模型邊界：交付規則、20個不含真密鑰的樣本、混淆矩陣及每項例外的範圍與到期日。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver the rule, twenty secret-free fixtures, confusion matrix and scoped, expiring exceptions.","difference":"為每個結果保留來源到輸出的路徑，判斷驗證是否支配所有可達分支，避免僅數警告。","differenceEn":"Retain source-to-sink paths and determine whether validation covers every reachable branch rather than just counting alerts.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["Precision=TP/(TP+FP)，recall=TP/(TP+FN)；語法匹配不等於跨函式資料流證明。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 20個自編片段中8個應命中；規則找到6個真陽性並誤報3個，漏2個。 Precision=6/9=66.6667%，recall=6/8=75%。","分流工作量=候選路徑數×每條檢查分鐘；結果去重需保留不同來源或不同控制缺口。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 查詢產生18條路徑，其中6條是同一來源與輸出對的重複展示；每條人工檢查4分鐘。 需審查12條唯一候選，預估12×4=48分鐘。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Precision=TP/(TP+FP) and recall=TP/(TP+FN); syntax matching is not proof of interprocedural data flow. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Of twenty original snippets, eight should match; the rule yields six true positives, three false positives and two false negatives. Precision=6/9=66.6667% and recall=6/8=75%.","Triage effort equals candidate paths times minutes per path; deduplication must preserve distinct sources or control gaps. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. A query produces eighteen paths, six duplicate presentations of the same source-sink pair; each unique path requires four minutes. Twelve unique candidates require an estimated 12×4=48 minutes.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-064","referenceUrls":["https://theupdateframework.io/docs/metadata/"],"title":"The Update Framework：更新新鮮度與角色分權","titleEn":"The Update Framework: freshness and separated update roles","why":"用兩課的可觀察驗收條件比較模型邊界：交付規則、20個不含真密鑰的樣本、混淆矩陣及每項例外的範圍與到期日。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver the rule, twenty secret-free fixtures, confusion matrix and scoped, expiring exceptions.","difference":"分開root、targets、snapshot、timestamp責任，對過期、回退與不符大小的資料明確拒絕。","differenceEn":"Separate root, targets, snapshot and timestamp responsibilities; explicitly reject expired, rolled-back and size-mismatched metadata.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["Precision=TP/(TP+FP)，recall=TP/(TP+FN)；語法匹配不等於跨函式資料流證明。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 20個自編片段中8個應命中；規則找到6個真陽性並誤報3個，漏2個。 Precision=6/9=66.6667%，recall=6/8=75%。","新鮮度剩餘=到期時間−固定驗證起點；同一次更新應使用一致起點，不能逐步延後使過期資料續命。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 合成timestamp在12:00到期，驗證起點為09:30；root要求3把授權金鑰中至少2把有效簽署。 新鮮度剩餘2.5小時=150分鐘；有效簽署2把恰好達門檻。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Precision=TP/(TP+FP) and recall=TP/(TP+FN); syntax matching is not proof of interprocedural data flow. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Of twenty original snippets, eight should match; the rule yields six true positives, three false positives and two false negatives. Precision=6/9=66.6667% and recall=6/8=75%.","Remaining freshness equals expiry minus a fixed update-start time; use one start time throughout an update. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. A synthetic timestamp expires at 12:00 with validation beginning at 09:30; root requires two valid signatures among three authorized keys. Remaining freshness is 2.5 hours=150 minutes; two valid signatures exactly meet the threshold.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-6c0c13fca98291ab","url":"https://codeql.github.com/docs/writing-codeql-queries/","title":"Writing CodeQL queries","titleEn":"Writing CodeQL queries","publisher":"GitHub","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-026fe1f9ea5111a8","url":"https://theupdateframework.io/docs/metadata/","title":"TUF roles and metadata","titleEn":"TUF roles and metadata","publisher":"The Update Framework","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
